 .check-item input[type="checkbox"] { width:18px; height:18px; accent-color: var(--accent); flex-shrink:0; cursor: pointer; }

 .check-item label { cursor: pointer; flex:1; user-select: none; }

 .check-item.done label { text-decoration: line-through; color: var(--muted); }

 .export-section {

 background: var(--panel);

 border:1px solid var(--border);

 border-radius: var(--radius);

 padding: var(--gap);

 display: grid;

 gap:10px;

 }

 .export-preview {

 min-height:100px;

 max-height:280px;

 overflow-y: auto;

 background: var(--bg);

