 @media print {

 header, .paste-section, .card-actions, .flags-panel summary, .checklist-panel summary, .export-section, footer, .btn { display: none !important; }

 .app { height: auto; max-width: none; padding:0; }

 .card { break-inside: avoid; box-shadow: none; border:1px solid #ccc; background: white; color: black; }

 .card-type { border-color: currentColor; color: black; background: #f0f0f0; }

 .card-content { color: black; }

 .export-preview { display: none; }

 }

