<script>

// ============================================================

// Answer Evidence Balance Board — DOM-only construction// ============================================================/** @type {Array<{id:string, type:string, content:string, order:number}>} */

let cards = [];

let nextId =1;

let dragSrc = null;



// --- DOM Refs ---

const pasteInput = document.getElementById('paste-input');

const cardsSection = document.getElementById('cards-section');

const emptyState = document.getElementById('empty-state');

const flagsCount = document.getElementById('flags-count');

const flagsList = document.getElementById('flags-list');

const checklistItems = document.getElementById('checklist-items');

const exportPreview = document.getElementById('export-preview');



// --- Constants ---

const TYPE_LABELS = {

 claim: 'Claim',

 evidence: 'Evidence',

 helpfulness: 'Helpfulness',

 other: 'Other'

};



const SELF_PROMO_PATTERNS = [

 /\b(my|our)\s+(product|tool|service|platform|startup|company|business|app|software|solution|offering)\b/i,

 /\b(check out|try out|take a look at)\s+(my|our)\b/i,

 /\bI\s+(built|created|launched|founded|developed|made)\b/i,

 /\bvisit\s+(my|our)\s+\S+\b/i,

 /\bgithub\.com\/[^/]+\/[^/]+\b/i,

 /\b[A-Za-z0-9-]+\.(com|io|dev|app|ai)\b/,

 /\b(sign up|subscribe|join)\s+(my|our)\b/i,

 /\bnewsletter\b/i,

 /\bdiscord\.gg\/\S+\b/i,

];



const UNSUPPORTED_CLAIM_PATTERNS = [

 /^\s*\[(insert|add|include|put)\s+(table|screenshot|benchmark|link|chart|graph|data|figure|image)\]/i,

 /^\s*\[.*?(citation|reference|source|evidence|proof|data)\s*(needed|required|here|missing|todo)\]/i,

 /^\[\s*(\d+|ref|citation|cite|source)\s*\]\s*$/i,

 /^\[\s*citation\s+needed\s*\]\s*$/i,

];



const WEAK_EVIDENCE_PATTERNS = [

 /^(in my experience|personally|i think|i believe|i feel|from what i'?ve seen|anecdotally)\b/i,

 /^(generally|usually|typically|often|many people|most developers|everyone knows)\b/i,

 /^(studies show|research shows|experts say|it is known|it'?s well known)\b/i,

];



const HELPFULNESS_KEYWORDS = [

 'step', 'example', 'code', 'snippet', 'config', 'command', 'install', 'run',

 'usage', 'api', 'parameter', 'option', 'flag', 'workaround', 'fix', 'solution',

 'troubleshoot', 'debug', 'error', 'warning', 'note', 'tip', 'caveat', 'gotcha'

];



const CITATION_PATTERN = /\[(\d+|[a-z]+)\]|\((?:https?:\/\/|doi:|arxiv:)[^)]+\)/gi;

const URL_PATTERN = /https?:\/\/[^\s)]+/gi;

const DOI_PATTERN = /\b10\.\d{4,9}\/[-._;()/:A-Z0-9]+\b/i;

const ISBN_PATTERN = /\b(?:ISBN[- ]?)?(?:97[89][- ]?)?\d{1,5}[- ]?\d{1,7}[- ]?\d{1,6}[- ]?[\dX]\b/i;



// --- Utility ---

function uid() { return `card-${nextId++}-${Math.random().toString(36).slice(2,6)}`; }

function escapeHtml(s) { return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

function debounce(fn, ms =150) { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; }

function createEl(tag, props = {}, children = []) {

 const el = document.createElement(tag);

 Object.entries(props).forEach(([k, v]) => {

 if (k === 'text') el.textContent = v;

 else if (k === 'html') el.innerHTML = v; // only for empty-state svg which is static else if (k.startsWith('on') && typeof v === 'function') el.addEventListener(k.slice(2), v);

 else if (k === 'dataset') Object.entries(v).forEach(([dk, dv]) => el.dataset[dk] = dv);

 else el.setAttribute(k, v);

 });

 children.forEach(c => { if (c instanceof Node) el.appendChild(c); else if (c != null) el.appendChild(document.createTextNode(String(c))); });

 return el;

}



// --- Classification ---

function classifyText(text) {

 const t = text.trim().toLowerCase();

 if (!t) return 'other';

 if (/^\[?(claim|assertion|statement)\]?/i.test(t)) return 'claim';

 if (/^\[?(evidence|proof|source|citation|reference|data|benchmark|study)\]?/i.test(t)) return 'evidence';

 if (/^\[?(helpful|helpfulness|tip|example|step|workaround|solution|fix|note|caveat)\]?/i.test(t)) return 'helpfulness';

 const hasCitation = CITATION_PATTERN.test(text) || URL_PATTERN.test(text) || DOI_PATTERN.test(text) || ISBN_PATTERN.test(text);

 const hasCode = /```|`[^`]+`|^\s{4}\S/m.test(text);

 const hasSteps = /^\s*(\d+\.|[-*])\s/.test(text) || /\b(step \d|first|next|then|finally)\b/i.test(text);

 const isShort = text.split(/\s+/).length < 12;

 if (hasCitation || hasCode) return 'evidence';

 if (hasSteps || HELPFULNESS_KEYWORDS.some(k => new RegExp(`\\b${k}\\b`, 'i').test(text))) return 'helpfulness';

 if (WEAK_EVIDENCE_PATTERNS.some(r => r.test(t))) return 'claim';

 if (isShort && /^(this|that|it|the|a|an)\b/i.test(t)) return 'claim';

 return /[.!?]$/.test(text.trim()) ? 'claim' : 'other';

}



// --- Detection ---

function detectSelfPromo(text) {

 const hits = [];

 for (const rx of SELF_PROMO_PATTERNS) {

 const m = text.match(rx);

 if (m) hits.push({ pattern: rx.source, match: m[0], index: m.index });

 }

 return hits;

}

function detectUnsupportedClaims(text) {

 const hits = [];

 for (const rx of UNSUPPORTED_CLAIM_PATTERNS) {

 const m = text.match(rx);

 if (m) hits.push({ pattern: rx.source, match: m[0], index: m.index });

 }

 return hits;

}

function detectWeakEvidence(text) {

 const hits = [];

 for (const rx of WEAK_EVIDENCE_PATTERNS) {

 const m = text.match(rx);

 if (m) hits.push({ pattern: rx.source, match: m[0], index: m.index });

 }

 return hits;

}

function hasCitation(text) {

 return CITATION_PATTERN.test(text) || URL_PATTERN.test(text) || DOI_PATTERN.test(text) || ISBN_PATTERN.test(text);

}

function extractSnippet(text, index, radius =40) {

 if (index === undefined) return text.slice(0,80);

 const start = Math.max(0, index - radius);

 const end = Math.min(text.length, index + radius);

 let snip = text.slice(start, end);

 if (start >0) snip = '…' + snip;

 if (end < text.length) snip = snip + '…';

 return snip;

}



// --- Card Rendering ---

function renderCards() {

 // Clear existing cards (keep emptyState)

 [...cardsSection.children].forEach(child => { if (child !== emptyState) child.remove(); });



 if (cards.length ===0) {

 emptyState.hidden = false;

 return;

 }

 emptyState.hidden = true;



 for (const card of cards) {

 const article = createEl('article', {

 className: 'card',

 dataset: { id: card.id },

 draggable: true,

 role: 'listitem'

 });



 // Header const header = createEl('div', { className: 'card-header' });



 // Type select const select = createEl('select', {

 className: `card-type type-${card.type}`,

 'aria-label': 'Card type'

 });

 Object.entries(TYPE_LABELS).forEach(([value, label]) => {

 const opt = createEl('option', { value, selected: value === card.type }, label);

 select.appendChild(opt);

 });

 select.addEventListener('change', e => {

 card.type = e.target.value;

 e.target.className = `card-type type-${card.type}`;

 debouncedAnalyze();

 });

 header.appendChild(select);



 // Drag handle const dragHandle = createEl('span', { className: 'card-drag', 'aria-label': 'Drag to reorder', tabindex:0 }, '⋮⋮');

 header.appendChild(dragHandle);



 // Actions const actions = createEl('div', { className: 'card-actions' });

 const dupBtn = createEl('button', { className: 'btn ghost', 'aria-label': 'Duplicate', dataset: { action: 'duplicate' } }, '⎘');

 const delBtn = createEl('button', { className: 'btn ghost danger', 'aria-label': 'Delete', dataset: { action: 'delete' } }, '✕');

 actions.appendChild(dupBtn);

 actions.appendChild(delBtn);

 header.appendChild(actions);



 article.appendChild(header);



 // Content const contentDiv = createEl('div', {

 className: 'card-content',

 contentEditable: true,

 'data-placeholder': 'Type or edit…',

 'aria-label': 'Card content',

 spellcheck: true,

 text: card.content });

 contentDiv.addEventListener('input', debounce(() => {

 card.content = contentDiv.textContent;

 debouncedAnalyze();

 },200));

 article.appendChild(contentDiv);



 // Action handlers dupBtn.addEventListener('click', () => {

 const idx = cards.indexOf(card);

 cards.splice(idx +1,0, { id: uid(), type: card.type, content: card.content, order: Date.now() });

 renumber();

 renderCards();

 debouncedAnalyze();

 });

 delBtn.addEventListener('click', () => {

 cards = cards.filter(c => c.id !== card.id);

 renumber();

 renderCards();

 debouncedAnalyze();

 });



 // Drag & drop article.addEventListener('dragstart', e => {

 dragSrc = article;

 e.dataTransfer.effectAllowed = 'move';

 article.classList.add('dragging');

 });

 article.addEventListener('dragend', () => {

 article.classList.remove('dragging');

 dragSrc = null;

 });

 article.addEventListener('dragover', e => { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; });

 article.addEventListener('drop', e => {

 e.preventDefault();

 if (dragSrc && dragSrc !== article) {

 const from = cards.findIndex(c => c.id === dragSrc.dataset.id);

 const to = cards.findIndex(c => c.id === article.dataset.id);

 const [moved] = cards.splice(from,1);

 cards.splice(to,0, moved);

 renumber();

 renderCards();

 debouncedAnalyze();

 }

 });



 // Keyboard reorder dragHandle.addEventListener('keydown', e => {

 if (e.key === 'Enter' || e.key === ' ') {

 e.preventDefault();

 const idx = cards.findIndex(c => c.id === card.id);

 if (e.shiftKey && idx >0) { [cards[idx], cards[idx-1]] = [cards[idx-1], cards[idx]]; }

 else if (!e.shiftKey && idx < cards.length -1) { [cards[idx], cards[idx+1]] = [cards[idx+1], cards[idx]]; }

 else return;

 renumber();

 renderCards();

 debouncedAnalyze();

 }

 });



 cardsSection.appendChild(article);

 }

}

function renumber() { cards.forEach((c, i) => c.order = i); }



// --- Analysis ---

function analyze() {

 const flags = [];

 const checklistSet = new Set();



 for (const card of cards) {

 const text = card.content;



 // Self-promo for (const hit of detectSelfPromo(text)) {

 flags.push({

 severity: 'warn',

 type: 'self-promo',

 message: 'Possible self-promotion detected',

 snippet: extractSnippet(text, hit.index),

 cardId: card.id,

 fix: 'Remove or disclose affiliation'

 });

 }



 if (card.type === 'claim') {

 for (const hit of detectUnsupportedClaims(text)) {

 flags.push({

 severity: 'warn',

 type: 'placeholder',

 message: 'Placeholder citation/marker found',

 snippet: extractSnippet(text, hit.index),

 cardId: card.id,

 fix: 'Replace with real citation'

 });

 }

 for (const hit of detectWeakEvidence(text)) {

 flags.push({

 severity: 'warn',

 type: 'weak-evidence',

 message: 'Claim uses weak/hedging language',

 snippet: extractSnippet(text, hit.index),

 cardId: card.id,

 fix: 'Add concrete evidence or cite source'

 });

 }

 if (!hasCitation(text) && text.trim().length >30) {

 flags.push({

 severity: 'danger',

 type: 'uncited-claim',

 message: 'Claim appears uncited',

 snippet: extractSnippet(text),

 cardId: card.id,

 fix: 'Add citation, link, or evidence card'

 });

 checklistSet.add(`Add source for: "${extractSnippet(text,0,60)}"`);

 }

 }



 if (card.type === 'evidence') {

 if (!hasCitation(text) && !/```|`[^`]+`|^\s{4}\S/m.test(text)) {

 flags.push({

 severity: 'warn',

 type: 'thin-evidence',

 message: 'Evidence card lacks citation/code/data',

 snippet: extractSnippet(text),

 cardId: card.id,

 fix: 'Add link, DOI, ISBN, or code block'

 });

 }

 }

 }



 // Balance checks const claimCount = cards.filter(c => c.type === 'claim').length;

 const evidenceCount = cards.filter(c => c.type === 'evidence').length;

 const helpfulCount = cards.filter(c => c.type === 'helpfulness').length;



 if (claimCount >0 && evidenceCount ===0) {

 flags.unshift({

 severity: 'danger',

 type: 'balance',

 message: `${claimCount} claim(s) but0 evidence cards — answer lacks support`,

 snippet: '',

 cardId: null,

 fix: 'Add evidence cards with citations, data, or code'

 });

 } else if (claimCount > evidenceCount *2) {

 flags.unshift({

 severity: 'warn',

 type: 'balance',

 message: `High claim-to-evidence ratio (${claimCount}:${evidenceCount})`,

 snippet: '',

 cardId: null,

 fix: 'Add more evidence or reduce speculative claims'

 });

 }



 if (helpfulCount ===0 && claimCount >0) {

 checklistSet.add('Consider adding a helpfulness card (example, step, caveat, or workaround)');

 }



 // Render flags flagsCount.textContent = flags.length;

 flagsList.replaceChildren();

 for (const f of flags) {

 const item = createEl('div', { className: `flag-item ${f.severity === 'danger' ? 'danger' : ''}`, role: 'listitem' });

 const icon = createEl('span', { className: 'flag-icon', 'aria-hidden': 'true' }, f.severity === 'danger' ? '✖' : '⚠');

 if (f.type === 'self-promo') icon.textContent = '📢';

 item.appendChild(icon);



 const textDiv = createEl('div', { className: 'flag-text' });

 const strong = createEl('strong', {}, f.message);

 textDiv.appendChild(strong);

 if (f.snippet) {

 const br = createEl('br');

 const snip = createEl('span', { className: 'snippet' }, f.snippet);

 textDiv.appendChild(br);

 textDiv.appendChild(snip);

 }

 item.appendChild(textDiv);



 if (f.fix) {

 const fixBtn = createEl('button', { className: 'btn ghost flag-fix', 'aria-label': 'Copy fix suggestion', dataset: { fix: f.fix } }, f.fix);

 fixBtn.addEventListener('click', () => {

 navigator.clipboard.writeText(f.fix).then(() => {

 const orig = fixBtn.textContent;

 fixBtn.textContent = 'Copied!';

 setTimeout(() => fixBtn.textContent = orig,1200);

 });

 });

 item.appendChild(fixBtn);

 }



 if (f.cardId) {

 item.style.borderLeftColor = f.severity === 'danger' ? 'var(--danger)' : 'var(--warn)';

 }

 flagsList.appendChild(item);

 }



 // Render checklist checklistItems.replaceChildren();

 const sortedChecks = [...checklistSet].sort();

 if (sortedChecks.length ===0) {

 const msg = createEl('div', { style: 'color:var(--muted);font-size:0.85rem;padding:8px;' }, '✓ No outstanding source needs detected');

 checklistItems.appendChild(msg);

 } else {

 for (const text of sortedChecks) {

 const chkId = `chk-${uid()}`;

 const item = createEl('div', { className: 'check-item', role: 'listitem' });

 const input = createEl('input', { type: 'checkbox', id: chkId });

 const label = createEl('label', { htmlFor: chkId }, text);

 input.addEventListener('change', e => { item.classList.toggle('done', e.target.checked); });

 item.appendChild(input);

 item.appendChild(label);

 checklistItems.appendChild(item);

 }

 }



 buildExportPreview();

}



function buildExportPreview() {

 const claimCards = cards.filter(c => c.type === 'claim');

 const evidenceCards = cards.filter(c => c.type === 'evidence');

 const helpfulCards = cards.filter(c => c.type === 'helpfulness');

 const otherCards = cards.filter(c => c.type === 'other');



 let out = '';

 if (claimCards.length) {

 out += '## Answer\n\n';

 for (const c of claimCards) out += `${c.content.trim()}\n\n`;

 }

 if (evidenceCards.length) {

 out += '## Sources & Evidence\n\n';

 for (const c of evidenceCards) out += `- ${c.content.trim()}\n`;

 out += '\n';

 }

 if (helpfulCards.length) {

 out += '## Practical Guidance\n\n';

 for (const c of helpfulCards) out += `- ${c.content.trim()}\n`;

 out += '\n';

 }

 if (otherCards.length) {

 out += '## Notes\n\n';

 for (const c of otherCards) out += `- ${c.content.trim()}\n`;

 }



 exportPreview.textContent = out.trim() || 'Export preview appears here after analysis.';

 exportPreview.classList.toggle('empty', !out.trim());

}



// --- Split Logic ---

function splitIntoCards() {

 const raw = pasteInput.value.trim();

 if (!raw) return;



 let parts = raw.split(/\n\s*\n/).map(s => s.trim()).filter(Boolean);

 if (parts.length <=1) {

 parts = raw.split(/\n+/).map(s => s.trim()).filter(Boolean);

 }



 cards = parts.map((content, i) => ({

 id: uid(),

 type: classifyText(content),

 content,

 order: i }));

 renderCards();

 analyze();

 pasteInput.value = '';

}



// --- Export ---

function copyExport() {

 const text = exportPreview.textContent;

 if (text && !exportPreview.classList.contains('empty')) {

 navigator.clipboard.writeText(text).then(() => {

 const btn = document.getElementById('btn-copy');

 const orig = btn.textContent;

 btn.textContent = 'Copied!';

 setTimeout(() => btn.textContent = orig,1200);

 });

 }

}

function downloadExport(ext) {

 const text = exportPreview.textContent;

 if (!text || exportPreview.classList.contains('empty')) return;

 const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });

 const url = URL.createObjectURL(blob);

 const a = document.createElement('a');

 a.href = url;

 a.download = `answer-brief.${ext}`;

 a.click();

 URL.revokeObjectURL(url);

}



// --- Demo Data ---

function loadDemo() {

 const demo = `Our new framework "Velox" outperforms React by3x in benchmarks.



[Insert benchmark table here]



I built Velox because existing solutions were too slow. You can try it at github.com/myuser/velox.



In my experience, developers love the simple API.



Studies show that80% of users prefer faster load times.



Example usage:

\`\`\`jsimport { velox } from 'velox';

velox.render(<App />);

\`\`\`



Note: Velox requires Node18+.`;

 pasteInput.value = demo;

 splitIntoCards();

}



// --- Event Bindings ---

document.getElementById('btn-split').addEventListener('click', splitIntoCards);

document.getElementById('btn-clear').addEventListener('click', () => {

 cards = [];

 nextId =1;

 pasteInput.value = '';

 renderCards();

 analyze();

});

document.getElementById('btn-demo').addEventListener('click', loadDemo);

document.getElementById('btn-copy').addEventListener('click', copyExport);

document.getElementById('btn-download').addEventListener('click', () => downloadExport('txt'));

document.getElementById('btn-download-md').addEventListener('click', () => downloadExport('md'));



pasteInput.addEventListener('paste', e => {

 if (cards.length ===0) setTimeout(splitIntoCards,0);

});



const debouncedAnalyze = debounce(analyze,200);



document.addEventListener('keydown', e => {

 if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {

 e.preventDefault();

 splitIntoCards();

 }

});



// InitrenderCards();

analyze();

</script>

</body>

</html>

