@keyframes slideIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }



.card-header {

  display: flex;

  align-items: center;

  gap: 10px;

  flex-wrap: wrap;

}



.card-type {

  font-size: 0.7rem;

  font-weight: 700;

  text-transform: uppercase;

  letter-spacing: 0.06em;

  padding: 4px 10px;

  border-radius: 999px;

  border: 1px solid;

  background: rgba(246,173,85,0.15);

  color: var(--warn);

  border-color: var(--warn);

}



.card-type.type-evidence { background: rgba(104,211,145,0.15); color: var(--ok); border-color: var(--ok); }

.card-type.type-helpfulness { background: rgba(79,209,197,0.15); color: var(--accent); border-color: var(--accent); }

.card-type.type-other { background: rgba(139,149,161,0.15); color: var(--muted); border-color: var(--muted); }



.card-content {

  min-height: 60px;

  outline: none;

  white-space: pre-wrap;

  word-wrap: break-word;

  font-size: 0.95rem;

  line-height: 1.6;

}



.card-content:empty::before { content: attr(data-placeholder); color: var(--muted); opacity: 0.6; }



.card-actions { display: flex; gap: 6px; flex-wrap: wrap; }

.card-actions .btn { padding: 6px 12px; font-size: 0.75rem; }



.flags-panel {

  background: var(--panel);

  border: 1px solid var(--border);

  border-radius: var(--radius);

  padding: var(--gap);

  display: grid;

  gap: 10px;

}



.flags-panel summary {

  cursor: pointer;

  list-style: none;

  display: flex;

  align-items: center;

  gap: 10px;

  font-weight: 600;

  color: var(--text);

}



.flags-panel summary::-webkit-details-marker { display: none; }

.flags-panel summary::before { content: "▸"; font-size: 0.7rem; transition: transform 0.2s; color: var(--muted); }

.flags-panel[open] summary::before { transform: rotate(90deg); }



.flags-list { display: grid; gap: 8px; padding-top: 8px; }



.flag-item {

  display: grid;

  grid-template-columns: auto 1fr auto;

  gap: 10px;

  align-items: start;

  padding: 10px;

  background: var(--panel-2);

  border-radius: 8px;

  border-left: 3px solid var(--warn);

  font-size: 0.85rem;

}



.flag-item.danger { border-left-color: var(--danger); }

.flag-item.ok { border-left-color: var(--ok); }



.flag-icon { font-size: 1.1rem; line-height: 1; }

.flag-text { color: var(--text); }

.flag-text .snippet { background: var(--bg); padding: 2px 6px; border-radius: 4px; font-family: var(--font-mono); font-size: 0.8em; color: var(--accent); }

.flag-fix { white-space: nowrap; }



.checklist-panel {

  background: var(--panel);

  border: 1px solid var(--border);

  border-radius: var(--radius);

  padding: var(--gap);

  display: grid;

  gap: 10px;

}



.checklist-panel summary {

  cursor: pointer;

  list-style: none;

  display: flex;

  align-items: center;

  gap: 10px;

  font-weight: 600;

}



.checklist-panel summary::-webkit-details-marker { display: none; }

.checklist-panel summary::before { content: "▸"; font-size: 0.7rem; transition: transform 0.2s; color: var(--muted); }

.checklist-panel[open] summary::before { transform: rotate(90deg); }



.checklist-items { display: grid; gap: 6px; padding-top: 8px; }



.check-item {

  display: flex;

  align-items: center;

  gap: 10px;

  padding: 8px 10px;

  background: var(--panel-2);

  border-radius: 8px;

  font-size: 0.85rem;

  transition: background 0.15s;

}



.check-item:hover { background: var(--panel); }

.check-item input[type="checkbox"] { width: 18px; height: 18px; accent-color: var(--accent); flex-shrink: 0; cursor: pointer; }

.check-item label { cursor: pointer; flex: 1; user-select: none; }

.check-item.done label { text-decoration: line-through; color: var(--muted); }



.export-section {

  background: var(--panel);

  border: 1px solid var(--border);

  border-radius: var(--radius);

  padding: var(--gap);

  display: grid;

  gap: 10px;

}



.export-preview {

  min-height: 100px;

  max-height: 280px;

  overflow-y: auto;

  background: var(--bg);

  border: 1px solid var(--border);

  border-radius: 8px;

  padding: 12px;

  font-family: var(--font-mono);

  font-size: 0.8rem;

  line-height: 1.6;

  white-space: pre-wrap;

  word-wrap: break-word;

  color: var(--text);

}



.export-preview.empty { color: var(--muted); text-align: center; padding-top: 40px; }



.export-actions { display: flex; gap: 8px; flex-wrap: wrap; }



footer { text-align: center; color: var(--muted); font-size: 0.75rem; padding: 8px 0; }



.empty-state { text-align: center; padding: 40px 20px; color: var(--muted); }

.empty-state .icon { font-size: 48px; margin-bottom: 12px; opacity: 0.4; }



::-webkit-scrollbar { width: 8px; height: 8px; }

::-webkit-scrollbar-track { background: var(--bg); }

::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }

::-webkit-scrollbar-thumb:hover { background: var(--muted); }



@media (prefers-reduced-motion: reduce) { * { animation: none !important; transition: none !important; } }



@media print {

  header, .paste-section, .card-actions, .flags-panel summary, .checklist-panel summary, .export-section, footer, .btn { display: none !important; }

  .app { height: auto; max-width: none; padding: 0; }

  .card { break-inside: avoid; box-shadow: none; border: 1px solid #ccc; background: white; color: black; }

  .card-type { border-color: currentColor; color: black; background: #f0f0f0; }

  .card-content { color: black; }

  .export-preview { display: none; }

}

</style>

</head>

<body>

<div class="app">

  <header>

    <h1>Answer Evidence Balance Board</h1>

    <p>Paste → Split → Audit → Export</p>

  </header>



  <section class="paste-section" aria-label="Paste draft answer">

    <label for="paste-input">Draft Answer</label>

    <textarea id="paste-input" placeholder="Paste your draft answer here…&#10;&#10;Tip: Paragraphs separated by blank lines become individual cards. You can also edit cards directly after splitting."></textarea>

    <div class="paste-actions">

      <button class="btn primary" id="btn-split" type="button">Split into Cards</button>

      <button class="btn ghost" id="btn-clear" type="button">Clear All</button>

      <button class="btn ghost" id="btn-demo" type="button">Load Demo</button>

    </div>

  </section>



  <section class="cards-section" id="cards-section" aria-label="Claim, evidence, and helpfulness cards" role="list">

    <div class="empty-state" id="empty-state" role="status">

      <div class="icon" aria-hidden="true">📋</div>

      <p>No cards yet. Paste a draft and click <strong>Split into Cards</strong>.</p>

    </div>

  </section>



  <details class="flags-panel" id="flags-panel" aria-label="Balance flags">

    <summary><span id="flags-count">0</span> Balance Flags</summary>

    <div class="flags-list" id="flags-list" role="list" aria-live="polite"></div>

  </details>



  <details class="checklist-panel" id="checklist-panel" aria-label="Source needed checklist">

    <summary>Source-Needed Checklist</summary>

    <div class="checklist-items" id="checklist-items" role="list"></div>

  </details>



  <section class="export-section" aria-label="Export cleaned answer">

    <div class="export-preview empty" id="export-preview" aria-live="polite" role="textbox" readonly>Export preview appears here after analysis.</div>

    <div class="export-actions">

      <button class="btn primary" id="btn-copy" type="button">Copy Clean Answer</button>

      <button class="btn ghost" id="btn-download" type="button">Download .txt</button>

      <button class="btn ghost" id="btn-download-md" type="button">Download .md</button>

    </div>

  </section>



  <footer>

    <p>Works offline • No tracking • Save as HTML to reuse</p>

  </footer>

</div>



<script>

// ============================================================

// Answer Evidence Balance Board — DOM-only construction

// ============================================================



/** @type {Array<{id:string, type:string, content:string, order:number}>} */

let cards = [];

let nextId = 1;



// --- DOM Refs ---

const pasteInput = document.getElementById('paste-input');

const cardsSection = document.getElementById('cards-section');

const emptyState = document.getElementById('empty-state');

const flagsCount = document.getElementById('flags-count');

const flagsList = document.getElementById('flags-list');

const checklistItems = document.getElementById('checklist-items');

const exportPreview = document.getElementById('export-preview');



// --- Constants ---

const TYPE_LABELS = {

  claim: 'Claim',

  evidence: 'Evidence',

  helpfulness: 'Helpfulness',

  other: 'Other'

};



const SELF_PROMO_PATTERNS = [

  /\b(my|our)\s+(product|tool|service|platform|startup|company|business|app|software|solution|offering)\b/i,

  /\b(check out|try out|take a look at)\s+(my|our)\b/i,

  /\bI\s+(built|created|launched|founded|developed|made)\b/i,

  /\bvisit\s+(my|our)\s+\S+\b/i,

  /\bgithub\.com\/[^/]+\/[^/]+\b/i,

  /\b[A-Za-z0-9-]+\.(com|io|dev|app|ai)\b/,

  /\b(sign up|subscribe|join)\s+(my|our)\b/i,

  /\bnewsletter\b/i,

  /\bdiscord\.gg\/\S+\b/i,

];



const UNSUPPORTED_CLAIM_PATTERNS = [

  /^\s*\[(insert|add|include|put)\s+(table|screenshot|benchmark|link|chart|graph|data|figure|image)\]/i,

  /^\s*\[.*?(citation|reference|source|evidence|proof|data)\s*(needed|required|here|missing|todo)\]/i,

  /^\[\s*(\d+|ref|citation|cite|source)\s*\]\s*$/i,

  /^\[\s*citation\s+needed\s*\]\s*$/i,

];



const WEAK_EVIDENCE_PATTERNS = [

  /^(in my experience|personally|i think|i believe|i feel|from what i'?ve seen|anecdotally)\b/i,

  /^(generally|usually|typically|often|many people|most developers|everyone knows)\b/i,

  /^(studies show|research shows|experts say|it is known|it'?s well known)\b/i,

];



const HELPFULNESS_KEYWORDS = [

  'step', 'example', 'code', 'snippet', 'config', 'command', 'install', 'run',

  'usage', 'api', 'parameter', 'option', 'flag', 'workaround', 'fix', 'solution',

  'troubleshoot', 'debug', 'error', 'warning', 'note', 'tip', 'caveat', 'gotcha'

];



const CITATION_PATTERN = /\[(\d+|[a-z]+)\]|\((?:https?:\/\/|doi:|arxiv:)[^)]+\)/gi;

const URL_PATTERN = /https?:\/\/[^\s)]+/gi;

const DOI_PATTERN = /\b10\.\d{4,9}\/[-._;()/:A-Z0-9]+\b/i;

const ISBN_PATTERN = /\b(?:ISBN[- ]?)?(?:97[89][- ]?)?\d{1,5}[- ]?\d{1,7}[- ]?\d{1,6}[- ]?[\dX]\b/i;



// --- Utility ---

function uid() { return `card-${nextId++}-${Math.random().toString(36).slice(2,6)}`; }



function escapeHtml(s) {

  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

}



function debounce(fn, ms) {

  let t;

  return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };

}



function createEl(tag, props, children) {

  const el = document.createElement(tag);

  if (props) {

    Object.entries(props).forEach(([k, v]) => {

      if (k === 'text') {

        el.textContent = v;

      } else if (k === 'dataset') {

        Object.entries(v).forEach(([dk, dv]) => el.dataset[dk] = dv);

      } else if (k.startsWith('on') && typeof v === 'function') {

        el.addEventListener(k.slice(2), v);

      } else if (k === 'className') {

        el.className = v;

      } else if (k === 'htmlFor') {

        el.htmlFor = v;

      } else if (k === 'contentEditable') {

        el.contentEditable = v;

      } else if (k === 'spellcheck') {

        el.spellcheck = v;

      } else if (k === 'selected') {

        el.selected = v;

      } else if (k === 'draggable') {

        el.draggable = v;

      } else if (k === 'role') {

        el.setAttribute('role', v);

      } else if (k === 'aria-label') {

        el.setAttribute('aria-label', v);

      } else if (k === 'data-placeholder') {

        el.setAttribute('data-placeholder', v);

      } else {

        el.setAttribute(k, v);

      }

    });

  }

  if (children) {

    children.forEach(c => { if (c instanceof Node) el.appendChild(c); else if (c != null) el.appendChild(document.createTextNode(String(c))); });

  }

  return el;

}



// --- Classification ---

function classifyText(text) {

  const t = text.trim().toLowerCase();

  if (!t) return 'other';

  if (/^\[?(claim|assertion|statement)\]?/i.test(t)) return 'claim';

  if (/^\[?(evidence|proof|source|citation|reference|data|benchmark|study)\]?/i.test(t)) return 'evidence';

  if (/^\[?(helpful|helpfulness|tip|example|step|workaround|solution|fix|note|caveat)\]?/i.test(t)) return 'helpfulness';

  const hasCitation = CITATION_PATTERN.test(text) || URL_PATTERN.test(text) || DOI_PATTERN.test(text) || ISBN_PATTERN.test(text);

  const hasCode = /```|`[^`]+`|^\s{4}\S/m.test(text);

  const hasSteps = /^\s*(\d+\.|[-*])\s/.test(text) || /\b(step \d|first|next|then|finally)\b/i.test(text);

  const isShort = text.split(/\s+/).length < 12;

  if (hasCitation || hasCode) return 'evidence';

  if (hasSteps || HELPFULNESS_KEYWORDS.some(k => new RegExp('\\b' + k + '\\b', 'i').test(text))) return 'helpfulness';

  if (WEAK_EVIDENCE_PATTERNS.some(r => r.test(t))) return 'claim';

  if (isShort && /^(this|that|it|the|a|an)\b/i.test(t)) return 'claim';

  return /[.!?]$/.test(text.trim()) ? 'claim' : 'other';

}



// --- Detection ---

function detectSelfPromo(text) {

  const hits = [];

  for (const rx of SELF_PROMO_PATTERNS) {

    const m = text.match(rx);

    if (m) hits.push({ pattern: rx.source, match: m[0], index: m.index });

  }

  return hits;

}



function detectUnsupportedClaims(text) {

  const hits = [];

  for (const rx of UNSUPPORTED_CLAIM_PATTERNS) {

    const m = text.match(rx);

    if (m) hits.push({ pattern: rx.source, match: m[0], index: m.index });

  }

  return hits;

}



function detectWeakEvidence(text) {

  const hits = [];

  for (const rx of WEAK_EVIDENCE_PATTERNS) {

    const m = text.match(rx);

    if (m) hits.push({ pattern: rx.source, match: m[0], index: m.index });

  }

  return hits;

}



function hasCitation(text) {

  return CITATION_PATTERN.test(text) || URL_PATTERN.test(text) || DOI_PATTERN.test(text) || ISBN_PATTERN.test(text);

}



function extractSnippet(text, index, radius) {

  if (index === undefined) return text.slice(0, 80);

  const start = Math.max(0, index - radius);

  const end = Math.min(text.length, index + radius);

  let snip = text.slice(start, end);

  if (start > 0) snip = '…' + snip;

  if (end < text.length) snip = snip + '…';

  return snip;

}



// --- Card Rendering ---

function renderCards() {

  // Clear existing cards (keep emptyState)

  const children = Array.from(cardsSection.children);

  for (let i = 0; i < children.length; i++) {

    if (children[i] !== emptyState) children[i].remove();

  }



  if (cards.length === 0) {

    emptyState.hidden = false;

    return;

  }

  emptyState.hidden = true;



  for (const card of cards) {

    const article = createEl('article', {

      className: 'card',

      dataset: { id: card.id },

      draggable: false,

      role: 'listitem'

    });



    // Header

    const header = createEl('div', { className: 'card-header' });



    // Type select

    const select = createEl('select', {

      className: 'card-type type-' + card.type,

      'aria-label': 'Card type'

    });

    Object.entries(TYPE_LABELS).forEach(([value, label]) => {

      const opt = createEl('option', { value: value, selected: value === card.type }, label);

      select.appendChild(opt);

    });

    select.addEventListener('change', (e) => {

      card.type = e.target.value;

      e.target.className = 'card-type type-' + card.type;

      debouncedAnalyze();

    });

    header.appendChild(select);



    // Actions

    const actions = createEl('div', { className: 'card-actions' });

    const dupBtn = createEl('button', { className: 'btn ghost', 'aria-label': 'Duplicate', dataset: { action: 'duplicate' } }, '⎘');

    const delBtn = createEl('button', { className: 'btn ghost danger', 'aria-label': 'Delete', dataset: { action: 'delete' } }, '✕');

    actions.appendChild(dupBtn);

    actions.appendChild(delBtn);

    header.appendChild(actions);



    article.appendChild(header);



    // Content

    const contentDiv = createEl('div', {

      className: 'card-content',

      contentEditable: true,

      'data-placeholder': 'Type or edit…',

      'aria-label': 'Card content',

      spellcheck: true,

      text: card.content

    });

    contentDiv.addEventListener('input', debounce(() => {

      card.content = contentDiv.textContent;

      debouncedAnalyze();

    }, 200));

    article.appendChild(contentDiv);



    // Action handlers

    dupBtn.addEventListener('click', () => {

      const idx = cards.indexOf(card);

      cards.splice(idx + 1, 0, { id: uid(), type: card.type, content: card.content, order: Date.now() });

      renumber();

      renderCards();

      debouncedAnalyze();

    });



    delBtn.addEventListener('click', () => {

      cards = cards.filter(c => c.id !== card.id);

      renumber();

      renderCards();

      debouncedAnalyze();

    });



    cardsSection.appendChild(article);

  }

}



function renumber() { cards.forEach((c, i) => c.order = i); }



// --- Analysis ---

function analyze() {

  const flags = [];

  const checklistSet = new Set();



  for (const card of cards) {

    const text = card.content;



    // Self-promo

    for (const hit of detectSelfPromo(text)) {

      flags.push({

        severity: 'warn',

        type: 'self-promo',

        message: 'Possible self-promotion detected',

        snippet: extractSnippet(text, hit.index),

        cardId: card.id,

        fix: 'Remove or disclose affiliation'

      });

    }



    if (card.type === 'claim') {

      for (const hit of detectUnsupportedClaims(text)) {

        flags.push({

          severity: 'warn',

          type: 'placeholder',

          message: 'Placeholder citation/marker found',

          snippet: extractSnippet(text, hit.index),

          cardId: card.id,

          fix: 'Replace with real citation'

        });

      }

      for (const hit of detectWeakEvidence(text)) {

        flags.push({

          severity: 'warn',

          type: 'weak-evidence',

          message: 'Claim uses weak/hedging language',

          snippet: extractSnippet(text, hit.index),

          cardId: card.id,

          fix: 'Add concrete evidence or cite source'

        });

      }

      if (!hasCitation(text) && text.trim().length > 30) {

        flags.push({

          severity: 'danger',

          type: 'uncited-claim',

          message: 'Claim appears uncited',

          snippet: extractSnippet(text),

          cardId: card.id,

          fix: 'Add citation, link, or evidence card'

        });

        checklistSet.add('Add source for: "' + extractSnippet(text, 0, 60) + '"');

      }

    }



    if (card.type === 'evidence') {

      if (!hasCitation(text) && !/```|`[^`]+`|^\s{4}\S/m.test(text)) {

        flags.push({

          severity: 'warn',

          type: 'thin-evidence',

          message: 'Evidence card lacks citation/code/data',

          snippet: extractSnippet(text),

          cardId: card.id,

          fix: 'Add link, DOI, ISBN, or code block'

        });

      }

    }

  }



  // Balance checks

  const claimCount = cards.filter(c => c.type === 'claim').length;

  const evidenceCount = cards.filter(c => c.type === 'evidence').length;

  const helpfulCount = cards.filter(c => c.type === 'helpfulness').length;



  if (claimCount > 0 && evidenceCount === 0) {

    flags.unshift({

      severity: 'danger',

      type: 'balance',

      message: claimCount + ' claim(s) but 0 evidence cards — answer lacks support',

      snippet: '',

      cardId: null,

      fix: 'Add evidence cards with citations, data, or code'

    });

  } else if (claimCount > evidenceCount * 2) {

    flags.unshift({

      severity: 'warn',

      type: 'balance',

      message: 'High claim-to-evidence ratio (' + claimCount + ':' + evidenceCount + ')',

      snippet: '',

      cardId: null,

      fix: 'Add more evidence or reduce speculative claims'

    });

  }



  if (helpfulCount === 0 && claimCount > 0) {

    checklistSet.add('Consider adding a helpfulness card (example, step, caveat, or workaround)');

  }



  // Render flags

  flagsCount.textContent = flags.length;

  flagsList.replaceChildren();

  for (const f of flags) {

    const item = createEl('div', { className: 'flag-item' + (f.severity === 'danger' ? ' danger' : ''), role: 'listitem' });

    const iconChar = f.type === 'self-promo' ? '📢' : (f.severity === 'danger' ? '✖' : '⚠');

    const icon = createEl('span', { className: 'flag-icon', 'aria-hidden': 'true' }, iconChar);

    item.appendChild(icon);



    const textDiv = createEl('div', { className: 'flag-text' });

    const strong = createEl('strong', {}, f.message);

    textDiv.appendChild(strong);

    if (f.snippet) {

      textDiv.appendChild(createEl('br'));

      const snip = createEl('span', { className: 'snippet' }, f.snippet);

      textDiv.appendChild(snip);

    }

    item.appendChild(textDiv);



    if (f.fix) {

      const fixBtn = createEl('button', { className: 'btn ghost flag-fix', 'aria-label': 'Copy fix suggestion', dataset: { fix: f.fix } }, f.fix);

      fixBtn.addEventListener('click', () => {

        navigator.clipboard.writeText(f.fix).then(() => {

          const orig = fixBtn.textContent;

          fixBtn.textContent = 'Copied!';

          setTimeout(() => fixBtn.textContent = orig, 1200);

        });

      });

      item.appendChild(fixBtn);

    }



    if (f.cardId) {

      item.style.borderLeftColor = f.severity === 'danger' ? 'var(--danger)' : 'var(--warn)';

    }

    flagsList.appendChild(item);

  }



  // Render checklist

  checklistItems.replaceChildren();

  const sortedChecks = Array.from(checklistSet).sort();

  if (sortedChecks.length === 0) {

    const msg = createEl('div', { style: 'color:var(--muted);font-size:0.85rem;padding:8px;' }, '✓ No outstanding source needs detected');

    checklistItems.appendChild(msg);

  } else {

    for (const text of sortedChecks) {

      const chkId = 'chk-' + uid();

      const item = createEl('div', { className: 'check-item', role: 'listitem' });

      const input = createEl('input', { type: 'checkbox', id: chkId });

      const label = createEl('label', { htmlFor: chkId }, text);

      input.addEventListener('change', (e) => { item.classList.toggle('done', e.target.checked); });

      item.appendChild(input);

      item.appendChild(label);

      checklistItems.appendChild(item);

    }

  }



  buildExportPreview();

}



function buildExportPreview() {

  const claimCards = cards.filter(c => c.type === 'claim');

  const evidenceCards = cards.filter(c => c.type === 'evidence');

  const helpfulCards = cards.filter(c => c.type === 'helpfulness');

  const otherCards = cards.filter(c => c.type === 'other');



  let out = '';

  if (claimCards.length) {

    out += '## Answer\n\n';

    for (const c of claimCards) out += c.content.trim() + '\n\n';

